import re

# Token types
TOK_INT = 'INT'
TOK_FLOAT = 'FLOAT'
TOK_IDENT = 'IDENT'
TOK_OP = 'OP'
TOK_LPAREN = 'LPAREN'
TOK_RPAREN = 'RPAREN'
TOK_COMMA = 'COMMA'
TOK_EOF = 'EOF'

# Tokenizer
def tokenize(s: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        # Numbers
        if c.isdigit() or (c == '.' and i + 1 < n and s[i+1].isdigit()):
            j = i
            if c == '.':
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append((TOK_FLOAT, s[i:j]))
                i = j
            else:
                while j < n and s[j].isdigit():
                    j += 1
                if j < n and s[j] == '.':
                    j += 1
                    while j < n and s[j].isdigit():
                        j += 1
                    tokens.append((TOK_FLOAT, s[i:j]))
                else:
                    tokens.append((TOK_INT, s[i:j]))
                i = j
            continue
        # Identifiers
        if c.isalpha() or c == '_':
            j = i
            while j < n and (s[j].isalnum() or s[j] == '_'):
                j += 1
            tokens.append((TOK_IDENT, s[i:j]))
            i = j
            continue
        # Operators and punctuation
        if c == '(':
            tokens.append((TOK_LPAREN, c))
            i += 1
            continue
        if c == ')':
            tokens.append((TOK_RPAREN, c))
            i += 1
            continue
        if c == ',':
            tokens.append((TOK_COMMA, c))
            i += 1
            continue
        # Two-char operators
        if i + 1 < n:
            two = s[i:i+2]
            if two in ('==', '!=', '<=', '>=', '||', '&&'):
                tokens.append((TOK_OP, two))
                i += 2
                continue
        # Single-char operators
        if c in '+-*/%^!<>?:&|':
            tokens.append((TOK_OP, c))
            i += 1
            continue
        raise SyntaxError(f"Unexpected character: {c!r}")
    tokens.append((TOK_EOF, ''))
    return tokens


class Parser:
    def __init__(self, tokens: list[tuple[str, str]], env: dict[str, float] | None):
        self.tokens = tokens
        self.pos = 0
        self.env = env if env is not None else {}

    def peek(self) -> tuple[str, str]:
        return self.tokens[self.pos]

    def advance(self) -> tuple[str, str]:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, tok_type: str, value: str | None = None) -> tuple[str, str]:
        tok = self.advance()
        if tok[0] != tok_type or (value is not None and tok[1] != value):
            raise SyntaxError(f"Expected {tok_type} {value!r}, got {tok[1]!r}")
        return tok

    def parse(self) -> int | float:
        if self.peek()[0] == TOK_EOF:
            raise SyntaxError("Empty input")
        result = self.parse_conditional()
        if self.peek()[0] != TOK_EOF:
            raise SyntaxError(f"Trailing tokens: {self.peek()[1]!r}")
        return result

    def parse_conditional(self) -> int | float:
        # a ? b : c, right-associative
        cond = self.parse_or()
        if self.peek()[0] == TOK_OP and self.peek()[1] == '?':
            self.advance()
            then_branch = self.parse_conditional()
            self.expect(TOK_OP, ':')
            else_branch = self.parse_conditional()
            # Only evaluate the chosen branch
            if cond != 0:
                return then_branch
            else:
                return else_branch
        return cond

    def parse_or(self) -> int | float:
        left = self.parse_and()
        while self.peek()[0] == TOK_OP and self.peek()[1] == '||':
            self.advance()
            right = self.parse_and()
            left = 1 if (left != 0 or right != 0) else 0
        return left

    def parse_and(self) -> int | float:
        left = self.parse_comparison()
        while self.peek()[0] == TOK_OP and self.peek()[1] == '&&':
            self.advance()
            right = self.parse_comparison()
            left = 1 if (left != 0 and right != 0) else 0
        return left

    def parse_comparison(self) -> int | float:
        left = self.parse_additive()
        if self.peek()[0] == TOK_OP and self.peek()[1] in ('==', '!=', '<', '<=', '>', '>='):
            op = self.advance()[1]
            right = self.parse_additive()
            if op == '==':
                return 1 if left == right else 0
            elif op == '!=':
                return 1 if left != right else 0
            elif op == '<':
                return 1 if left < right else 0
            elif op == '<=':
                return 1 if left <= right else 0
            elif op == '>':
                return 1 if left > right else 0
            elif op == '>=':
                return 1 if left >= right else 0
        return left

    def parse_additive(self) -> int | float:
        left = self.parse_multiplicative()
        while self.peek()[0] == TOK_OP and self.peek()[1] in ('+', '-'):
            op = self.advance()[1]
            right = self.parse_multiplicative()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_multiplicative(self) -> int | float:
        left = self.parse_power()
        while self.peek()[0] == TOK_OP and self.peek()[1] in ('*', '/', '%'):
            op = self.advance()[1]
            right = self.parse_power()
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                if isinstance(left, int) and isinstance(right, int):
                    if left % right == 0:
                        left = left // right
                    else:
                        left = left / right
                else:
                    left = left / right
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError("modulo by zero")
                left = left % right
        return left

    def parse_power(self) -> int | float:
        # ^ is right-associative, binds tighter than unary minus on its left
        # So: -2^2 is -(2^2) = -4, 2^-1 is 2^(-1) = 0.5
        # We parse the base as a unary expression, then if ^ follows, parse exponent as power
        base = self.parse_unary()
        if self.peek()[0] == TOK_OP and self.peek()[1] == '^':
            self.advance()
            exponent = self.parse_power()  # right-associative
            if isinstance(base, int) and isinstance(exponent, int):
                if exponent < 0:
                    return base ** exponent  # This gives float in Python for negative exponent
                else:
                    return base ** exponent
            else:
                return base ** exponent
        return base

    def parse_unary(self) -> int | float:
        if self.peek()[0] == TOK_OP and self.peek()[1] in ('+', '-', '!'):
            op = self.advance()[1]
            operand = self.parse_unary()
            if op == '+':
                return +operand
            elif op == '-':
                return -operand
            elif op == '!':
                return 1 if operand == 0 else 0
        return self.parse_atom()

    def parse_atom(self) -> int | float:
        tok = self.peek()
        if tok[0] == TOK_INT:
            self.advance()
            return int(tok[1])
        elif tok[0] == TOK_FLOAT:
            self.advance()
            return float(tok[1])
        elif tok[0] == TOK_IDENT:
            self.advance()
            name = tok[1]
            # Check if it's a function call
            if self.peek()[0] == TOK_LPAREN:
                if name == 'abs':
                    self.expect(TOK_LPAREN)
                    arg = self.parse_conditional()
                    self.expect(TOK_RPAREN)
                    return abs(arg)
                elif name == 'min' or name == 'max':
                    self.expect(TOK_LPAREN)
                    args = [self.parse_conditional()]
                    while self.peek()[0] == TOK_COMMA:
                        self.advance()
                        args.append(self.parse_conditional())
                    self.expect(TOK_RPAREN)
                    if name == 'min':
                        return min(args)
                    else:
                        return max(args)
                else:
                    raise NameError(f"Unknown function: {name}")
            else:
                # Look up in env
                if name in self.env:
                    return self.env[name]
                else:
                    raise NameError(f"Unknown variable: {name}")
        elif tok[0] == TOK_LPAREN:
            self.advance()
            expr = self.parse_conditional()
            self.expect(TOK_RPAREN)
            return expr
        else:
            raise SyntaxError(f"Unexpected token: {tok[1]!r}")


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    tokens = tokenize(expr)
    parser = Parser(tokens, env)
    return parser.parse()
