    def remove(self, start, end):
        if start >= end:
            return
        out = []
        for s, e in self._iv:
            if e <= start or s >= end:
                out.append((s, e))
                continue
            if s < start:
                out.append((s, start))
            if e > end:
                out.append((end, e))
        self._iv = out

    def contains(self, x):
        i = bisect.bisect_left(self._iv, (x, x))
        return i < len(self._iv) and self._iv[i][0] <= x < self._iv[i][1]

    def free(self, lo, hi):
