import re
from typing import List, Optional, Tuple

class Version:
    __slots__ = ('major', 'minor', 'patch', 'prerelease', 'build')

    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[List[str]] = None, build: Optional[List[str]] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease if prerelease is not None else []
        self.build = build if build is not None else []

    def _precedence_key(self):
        # Returns a tuple for comparison
        # Release (no prerelease) > prerelease
        # For prerelease: compare identifiers
        if not self.prerelease:
            # Release: higher than any prerelease
            # Use a special marker: (1,) means release, (0, identifiers) means prerelease
            return (1, self.major, self.minor, self.patch)
        else:
            # Prerelease: (0, major, minor, patch, identifiers)
            # But we need to compare identifiers properly
            # We'll handle this in __lt__ etc.
            return (0, self.major, self.minor, self.patch, self.prerelease)

    def _compare_prerelease(self, other_prerelease: List[str]) -> int:
        """Compare two prerelease identifier lists. Returns -1, 0, 1."""
        # Both are non-empty lists of identifiers
        for i in range(min(len(self.prerelease), len(other_prerelease))):
            a = self.prerelease[i]
            b = other_prerelease[i]
            a_numeric = a.isdigit()
            b_numeric = b.isdigit()
            if a_numeric and b_numeric:
                a_int = int(a)
                b_int = int(b)
                if a_int < b_int:
                    return -1
                elif a_int > b_int:
                    return 1
            elif a_numeric and not b_numeric:
                # Numeric < alphanumeric
                return -1
            elif not a_numeric and b_numeric:
                # Alphanumeric > numeric
                return 1
            else:
                # Both alphanumeric: ASCII order
                if a < b:
                    return -1
                elif a > b:
                    return 1
        # All compared identifiers are equal
        if len(self.prerelease) < len(other_prerelease):
            return -1
        elif len(self.prerelease) > len(other_prerelease):
            return 1
        else:
            return 0

    def __lt__(self, other: 'Version') -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        # Compare major, minor, patch
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch
        # Same major.minor.patch
        # Prerelease rules:
        # - No prerelease > prerelease
        # - Both no prerelease: equal
        # - Both prerelease: compare identifiers
        if not self.prerelease and not other.prerelease:
            return False
        if not self.prerelease:
            # self is release, other is prerelease: self > other
            return False
        if not other.prerelease:
            # self is prerelease, other is release: self < other
            return True
        # Both have prerelease
        return self._compare_prerelease(other.prerelease) < 0

    def __gt__(self, other: 'Version') -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return not self.__le__(other)

    def __le__(self, other: 'Version') -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.__lt__(other) or self.__eq__(other)

    def __ge__(self, other: 'Version') -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.__gt__(other) or self.__eq__(other)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        # Build metadata ignored
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self.prerelease == other.prerelease)

    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)

    def __hash__(self) -> int:
        return hash((self.major, self.minor, self.patch, tuple(self.prerelease)))

    def __repr__(self) -> str:
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += "-" + ".".join(self.prerelease)
        if self.build:
            s += "+" + ".".join(self.build)
        return s


# Regex for valid version parts
# Numeric identifier: no leading zeros unless it's "0"
# Alphanumeric identifier: [0-9A-Za-z-]+
# Prerelease: dot-separated identifiers
# Build: dot-separated identifiers

def _validate_identifier(ident: str) -> bool:
    if not ident:
        return False
    if ident.isdigit():
        # No leading zeros unless it's exactly "0"
        if len(ident) > 1 and ident[0] == '0':
            return False
        return True
    else:
        # Must match [0-9A-Za-z-]+
        if re.fullmatch(r'[0-9A-Za-z-]+', ident):
            return True
        return False


def _validate_numeric_part(s: str) -> bool:
    if not s:
        return False
    if not s.isdigit():
        return False
    if len(s) > 1 and s[0] == '0':
        return False
    return True


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 version string."""
    if not isinstance(v, str):
        raise ValueError(f"Expected string, got {type(v)}")

    s = v.strip()
    if not s:
        raise ValueError("Empty version string")

    # Allow leading 'v' or '='
    if s[0] in ('v', '='):
        s = s[1:]

    if not s:
        raise ValueError("Empty version after prefix")

    # Split off build metadata
    build_part = None
    if '+' in s:
        idx = s.index('+')
        build_str = s[idx+1:]
        s = s[:idx]
        if not build_str:
            raise ValueError("Empty build metadata")
        build_ids = build_str.split('.')
        for bid in build_ids:
            if not _validate_identifier(bid):
                raise ValueError(f"Invalid build identifier: {bid}")
        build_part = build_ids

    # Split off prerelease
    prerelease_part = None
    if '-' in s:
        # Find the last '-' that's not part of build (build already removed)
        # Prerelease comes after patch, before build
        idx = s.rfind('-')
        prerelease_str = s[idx+1:]
        s = s[:idx]
        if not prerelease_str:
            raise ValueError("Empty prerelease")
        prerelease_ids = prerelease_str.split('.')
        for pid in prerelease_ids:
            if not _validate_identifier(pid):
                raise ValueError(f"Invalid prerelease identifier: {pid}")
        prerelease_part = prerelease_ids

    # Now s should be MAJOR.MINOR.PATCH
    parts = s.split('.')
    if len(parts) != 3:
        raise ValueError(f"Expected MAJOR.MINOR.PATCH, got {s}")

    major_str, minor_str, patch_str = parts

    if not _validate_numeric_part(major_str):
        raise ValueError(f"Invalid major version: {major_str}")
    if not _validate_numeric_part(minor_str):
        raise ValueError(f"Invalid minor version: {minor_str}")
    if not _validate_numeric_part(patch_str):
        raise ValueError(f"Invalid patch version: {patch_str}")

    major = int(major_str)
    minor = int(minor_str)
    patch = int(patch_str)

    return Version(major, minor, patch, prerelease_part, build_part)


# Comparator representation
class Comparator:
    def __init__(self, op: str, version: Version, is_partial: bool = False, 
                 partial_major: Optional[int] = None, partial_minor: Optional[int] = None,
                 partial_patch: Optional[int] = None):
        self.op = op  # '<', '<=', '>', '>=', '='
        self.version = version
        self.is_partial = is_partial
        self.partial_major = partial_major
        self.partial_minor = partial_minor
        self.partial_patch = partial_patch

    def matches(self, v: Version) -> bool:
        if self.op == '<':
            return v < self.version
        elif self.op == '<=':
            return v <= self.version
        elif self.op == '>':
            return v > self.version
        elif self.op == '>=':
            return v >= self.version
        elif self.op == '=':
            return v == self.version
        else:
            raise ValueError(f"Unknown operator: {self.op}")


def _parse_partial_version(s: str) -> Tuple[Optional[int], Optional[int], Optional[int], Optional[List[str]], Optional[List[str]]]:
    """
    Parse a possibly partial version string.
    Returns (major, minor, patch, prerelease, build) where any of major/minor/patch can be None.
    """
    s = s.strip()
    if not s:
        raise ValueError("Empty version string")

    # Allow leading 'v' or '='
    if s[0] in ('v', '='):
        s = s[1:]

    if not s:
        raise ValueError("Empty version after prefix")

    # Split off build metadata
    build_part = None
    if '+' in s:
        idx = s.index('+')
        build_str = s[idx+1:]
        s = s[:idx]
        if not build_str:
            raise ValueError("Empty build metadata")
        build_ids = build_str.split('.')
        for bid in build_ids:
            if not _validate_identifier(bid):
                raise ValueError(f"Invalid build identifier: {bid}")
        build_part = build_ids

    # Split off prerelease
    prerelease_part = None
    if '-' in s:
        idx = s.rfind('-')
        prerelease_str = s[idx+1:]
        s = s[:idx]
        if not prerelease_str:
            raise ValueError("Empty prerelease")
        prerelease_ids = prerelease_str.split('.')
        for pid in prerelease_ids:
            if not _validate_identifier(pid):
                raise ValueError(f"Invalid prerelease identifier: {pid}")
        prerelease_part = prerelease_ids

    # Now s should be MAJOR[.MINOR[.PATCH]] or X/x/*
    parts = s.split('.')

    major = None
    minor = None
    patch = None

    if len(parts) == 1:
        p = parts[0]
        if p in ('x', 'X', '*'):
            major = None
        elif _validate_numeric_part(p):
            major = int(p)
        else:
            raise ValueError(f"Invalid major version: {p}")
    elif len(parts) == 2:
        p0, p1 = parts
        if p0 in ('x', 'X', '*'):
            major = None
