        # If there are no comparators, there's no comparator with prerelease, so prerelease versions don't match.
        # Wait, the spec says: "a version with a prerelease only satisfies a set if some comparator in that set has a version with the same MAJOR.MINOR.PATCH and a prerelease"
        # If the set is empty, there are no comparators, so no comparator has a prerelease, so prerelease versions don't match.
        # But what about release versions? They should match.
        if v.prerelease:
            return False
        return True

