    if v.prerelease:
        # Some comparator must have the same M.m.p and a prerelease
        has_matching_prerelease_comparator = False
        for comp in comparators:
            if (comp.version.major == v.major and 
                comp.version.minor == v.minor and 
                comp.version.patch == v.patch and 
                comp.version.prerelease):
                has_matching_prerelease_comparator = True
                break
        if not has_matching_prerelease_comparator:
            return False

    # Check all comparators
    for comp in comparators:
        if not comp.matches(v):
            return False

    return True


def satisfies(version: str, rng: str) -> bool:
    """Check if a version string satisfies a range string."""
    v = parse(version)

    # Parse the range
    # Split by ||
    sets = rng.split('||')

    for set_str in sets:
        set_str = set_str.strip()
        if not set_str:
            # Empty set matches any release
            if not v.prerelease:
                return True
            continue

        comparators = _parse_comparator_set(set_str)
        if _set_matches(comparators, v):
            return True

    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Return the highest version string that satisfies the range, or None."""
    # Parse all versions
    parsed_versions = []
    for v_str in versions:
        try:
            v = parse(v_str)
            parsed_versions.append((v, v_str))
        except ValueError:
            # Skip invalid versions? Or raise? The spec says invalid range raises ValueError.
            # For versions, if they're invalid, we should probably skip them or raise.
            # Let's skip them for now, but actually the spec doesn't say. Let's assume they're valid.
            # Actually, let's raise if a version is invalid.
            raise

    # Find all that satisfy
    satisfying = []
    for v, v_str in parsed_versions:
        if satisfies(v_str, rng):
            satisfying.append((v, v_str))

    if not satisfying:
        return None

    # Find the max by SemVer precedence
    max_v = max(satisfying, key=lambda x: x[0])
    return max_v[1]
