            minor = None
        elif _validate_numeric_part(p1):
            minor = int(p1)
        else:
            raise ValueError(f"Invalid minor version: {p1}")
    elif len(parts) == 3:
        p0, p1, p2 = parts
        if p0 in ('x', 'X', '*'):
            major = None
        elif _validate_numeric_part(p0):
            major = int(p0)
        else:
            raise ValueError(f"Invalid major version: {p0}")

        if p1 in ('x', 'X', '*'):
            minor = None
        elif _validate_numeric_part(p1):
            minor = int(p1)
        else:
            raise ValueError(f"Invalid minor version: {p1}")

        if p2 in ('x', 'X', '*'):
            patch = None
        elif _validate_numeric_part(p2):
            patch = int(p2)
        else:
            raise ValueError(f"Invalid patch version: {p2}")
    else:
        raise ValueError(f"Too many version parts: {s}")

    return (major, minor, patch, prerelease_part, build_part)


def _make_version(major: int, minor: int, patch: int, prerelease: Optional[List[str]] = None, build: Optional[List[str]] = None) -> Version:
    return Version(major, minor, patch, prerelease, build)


def _expand_comparator(op: str, major: Optional[int], minor: Optional[int], patch: Optional[int], 
                       prerelease: Optional[List[str]], build: Optional[List[str]]) -> List[Comparator]:
    if major is not None and minor is not None and patch is not None:
        v = _make_version(major, minor, patch, prerelease, build)
        return [Comparator(op, v)]

    if major is None:
        v = _make_version(0, 0, 0, prerelease, build)
        return [Comparator(op, v)]

    if minor is None:
        if op == '=':
            lower = _make_version(major, 0, 0, None, None)
            upper = _make_version(major + 1, 0, 0, None, None)
            return [Comparator('>=', lower), Comparator('<', upper)]
        elif op == '>':
            v = _make_version(major + 1, 0, 0, None, None)
            return [Comparator('>=', v)]
        elif op == '<=':
            v = _make_version(major + 1, 0, 0, None, None)
            return [Comparator('<', v)]
        elif op == '<':
            v = _make_version(major, 0, 0, None, None)
            return [Comparator('<', v)]
        elif op == '>=':
            v = _make_version(major, 0, 0, None, None)
            return [Comparator('>=', v)]

    if patch is None:
        if op == '=':
            lower = _make_version(major, minor, 0, None, None)
            upper = _make_version(major, minor + 1, 0, None, None)
            return [Comparator('>=', lower), Comparator('<', upper)]
        elif op == '>':
            v = _make_version(major, minor + 1, 0, None, None)
            return [Comparator('>=', v)]
        elif op == '<=':
            v = _make_version(major, minor + 1, 0, None, None)
            return [Comparator('<', v)]
        elif op == '<':
            v = _make_version(major, minor, 0, None, None)
            return [Comparator('<', v)]
        elif op == '>=':
            v = _make_version(major, minor, 0, None, None)
            return [Comparator('>=', v)]

    raise ValueError("Unexpected state in _expand_comparator")


def _parse_comparator_set(s: str) -> List[Comparator]:
    s = s.strip()
    if not s:
        return []

    # Check for hyphen range
    hyphen_match = re.match(r'^(\S+)\s*-\s*(\S+)$', s)
    if hyphen_match:
        left_str = hyphen_match.group(1)
        right_str = hyphen_match.group(2)

        left_major, left_minor, left_patch, left_pre, left_build = _parse_partial_version(left_str)
        right_major, right_minor, right_patch, right_pre, right_build = _parse_partial_version(right_str)

        if left_major is None:
            left_major = 0
        if left_minor is None:
            left_minor = 0
        if left_patch is None:
            left_patch = 0

        lower = _make_version(left_major, left_minor, left_patch, left_pre, left_build)

        if right_major is not None and right_minor is not None and right_patch is not None:
            upper = _make_version(right_major, right_minor, right_patch, right_pre, right_build)
            return [Comparator('>=', lower), Comparator('<=', upper)]
        else:
            if right_major is None:
                return [Comparator('>=', lower)]
            elif right_minor is None:
                upper = _make_version(right_major + 1, 0, 0, None, None)
                return [Comparator('>=', lower), Comparator('<', upper)]
            else:
                upper = _make_version(right_major, right_minor + 1, 0, None, None)
                return [Comparator('>=', lower), Comparator('<', upper)]

    tokens = s.split()
    if not tokens:
        return []

    comparators = []
    for token in tokens:
        op = '='
        version_str = token

        if token.startswith('<='):
            op = '<='
            version_str = token[2:]
        elif token.startswith('>='):
            op = '>='
            version_str = token[2:]
        elif token.startswith('<'):
            op = '<'
            version_str = token[1:]
        elif token.startswith('>'):
            op = '>'
            version_str = token[1:]
        elif token.startswith('='):
            op = '='
            version_str = token[1:]
        else:
            op = '='
            version_str = token

        if not version_str:
            raise ValueError(f"Empty version in comparator: {token}")

        if version_str.startswith('~'):
            version_str = version_str[1:]
            major, minor, patch, prerelease, build = _parse_partial_version(version_str)

            if major is None:
                lower = _make_version(0, 0, 0, None, None)
                upper = _make_version(1, 0, 0, None, None)
                comparators.extend([Comparator('>=', lower), Comparator('<', upper)])
            elif minor is None:
                lower = _make_version(major, 0, 0, None, None)
                upper = _make_version(major + 1, 0, 0, None, None)
                comparators.extend([Comparator('>=', lower), Comparator('<', upper)])
            elif patch is None:
                lower = _make_version(major, minor, 0, None, None)
                upper = _make_version(major, minor + 1, 0, None, None)
                comparators.extend([Comparator('>=', lower), Comparator('<', upper)])
            else:
                lower = _make_version(major, minor, patch, prerelease, build)
                if major == 0:
                    if minor == 0:
                        upper = _make_version(0, 0, patch + 1, None, None)
                    else:
                        upper = _make_version(0, minor + 1, 0, None, None)
                else:
                    upper = _make_version(major, minor + 1, 0, None, None)
                comparators.extend([Comparator('>=', lower), Comparator('<', upper)])

            continue

        elif version_str.startswith('^'):
            version_str = version_str[1:]
            major, minor, patch, prerelease, build = _parse_partial_version(version_str)

            if major is None:
                lower = _make_version(0, 0, 0, None, None)
                upper = _make_version(1, 0, 0, None, None)
                comparators.extend([Comparator('>=', lower), Comparator('<', upper)])
            elif minor is None:
                lower = _make_version(major, 0, 0, None, None)
                if major == 0:
                    upper = _make_version(1, 0, 0, None, None)
                else:
                    upper = _make_version(major + 1, 0, 0, None, None)
                comparators.extend([Comparator('>=', lower), Comparator('<', upper)])
            elif patch is None:
                lower = _make_version(major, minor, 0, None, None)
                if major == 0:
                    if minor == 0:
                        upper = _make_version(0, 1, 0, None, None)
                    else:
                        upper = _make_version(0, minor + 1, 0, None, None)
                else:
                    upper = _make_version(major + 1, 0, 0, None, None)
                comparators.extend([Comparator('>=', lower), Comparator('<', upper)])
            else:
                lower = _make_version(major, minor, patch, prerelease, build)
                if major == 0:
                    if minor == 0:
                        upper = _make_version(0, 0, patch + 1, None, None)
                    else:
                        upper = _make_version(0, minor + 1, 0, None, None)
                else:
                    upper = _make_version(major + 1, 0, 0, None, None)
                comparators.extend([Comparator('>=', lower), Comparator('<', upper)])

            continue

        major, minor, patch, prerelease, build = _parse_partial_version(version_str)
        expanded = _expand_comparator(op, major, minor, patch, prerelease, build)
        comparators.extend(expanded)

    return comparators


def _set_matches(comparators: List[Comparator], v: Version) -> bool:
    if not comparators:
        if v.prerelease:
            return False
        return True

    if v.prerelease:
        has_matching_prerelease_comparator = False
        for comp in comparators:
            if (comp.version.major == v.major and 
                comp.version.minor == v.minor and 
                comp.version.patch == v.patch and 
                comp.version.prerelease):
                has_matching_prerelease_comparator = True
                break
        if not has_matching_prerelease_comparator:
            return False

    for comp in comparators:
        if not comp.matches(v):
            return False

    return True


def satisfies(version: str, rng: str) -> bool:
    v = parse(version)

    sets = rng.split('||')

    for set_str in sets:
        set_str = set_str.strip()
        if not set_str:
            if not v.prerelease:
                return True
            continue

        comparators = _parse_comparator_set(set_str)
        if _set_matches(comparators, v):
            return True

    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    parsed_versions = []
    for v_str in versions:
        v = parse(v_str)
        parsed_versions.append((v, v_str))

    satisfying = []
    for v, v_str in parsed_versions:
        if satisfies(v_str, rng):
            satisfying.append((v, v_str))

    if not satisfying:
        return None

    max_v = max(satisfying, key=lambda x: x[0])
    return max_v[1]
