def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Split a command line into words according to a subset of POSIX shell rules.
    """
    i = 0
    n = len(line)
    words = []

    def expand_string(s: str, env: dict[str, str]) -> str:
        """Expand $ variables in a string."""
        result = []
        i = 0
        n = len(s)
        while i < n:
            if s[i] == '$':
                i += 1
                if i < n and s[i] == '{':
                    i += 1
                    start = i
                    while i < n and s[i] != '}':
                        i += 1
                    if i >= n:
                        raise ValueError("Unterminated ${")
                    inner = s[start:i]
                    i += 1
                    if ':-' in inner:
                        name, default = inner.split(':-', 1)
                        if name not in env or env[name] == '':
                            result.append(expand_string(default, env))
                        else:
                            result.append(env[name])
                    elif '-' in inner:
                        name, default = inner.split('-', 1)
                        if name not in env:
                            result.append(expand_string(default, env))
                        else:
                            result.append(env[name])
                    else:
                        name = inner
                        if name in env:
                            result.append(env[name])
                        else:
                            result.append('')
                elif i < n and (s[i].isalpha() or s[i] == '_'):
                    start = i
                    while i < n and (s[i].isalnum() or s[i] == '_'):
                        i += 1
                    name = s[start:i]
                    if name in env:
                        result.append(env[name])
                    else:
                        result.append('')
                else:
                    result.append('$')
            else:
                result.append(s[i])
                i += 1
        return ''.join(result)

    while i < n:
        # Skip whitespace
        while i < n and line[i] in ' \t\n':
            i += 1
        if i >= n:
            break

        # Build a word
        word_segments = []  # list of (text, is_quoted)
        had_empty_quoted = False
        all_unquoted_expansions = True
        expansion_total = ''

        while i < n and line[i] not in ' \t\n':
            c = line[i]

            if c == "'":
                # Single quote
                i += 1
                start = i
                while i < n and line[i] != "'":
                    i += 1
                if i >= n:
                    raise ValueError("Unterminated single quote")
                text = line[start:i]
                i += 1  # skip closing quote
                word_segments.append((text, True))
                all_unquoted_expansions = False
            elif c == '"':
                # Double quote
                i += 1
                text = []
                while i < n and line[i] != '"':
                    if line[i] == '\\':
                        if i + 1 < n:
                            next_c = line[i + 1]
                            if next_c in '$"\\\n':
                                if next_c == '\n':
                                    # Backslash-newline is removed
                                    i += 2
                                else:
                                    text.append(next_c)
                                    i += 2
                            else:
                                # Other backslash stays as is
                                text.append('\\')
                                text.append(next_c)
                                i += 2
                        else:
                            raise ValueError("Trailing unescaped backslash")
                    elif line[i] == '$':
                        # Expansion inside double quotes
                        i += 1
                        if i < n and line[i] == '{':
                            # ${...}
                            i += 1
                            start = i
                            while i < n and line[i] != '}':
                                i += 1
                            if i >= n:
                                raise ValueError("Unterminated ${")
                            inner = line[start:i]
                            i += 1  # skip }
                            # Parse the inner
                            if ':-' in inner:
                                name, default = inner.split(':-', 1)
                                if name not in env or env[name] == '':
                                    # Expand default
                                    default_expanded = expand_string(default, env)
                                    text.append(default_expanded)
                                else:
                                    text.append(env[name])
                            elif '-' in inner:
                                name, default = inner.split('-', 1)
                                if name not in env:
                                    default_expanded = expand_string(default, env)
                                    text.append(default_expanded)
                                else:
                                    text.append(env[name])
                            else:
                                name = inner
                                if name in env:
                                    text.append(env[name])
                                else:
                                    text.append('')
                        elif i < n and (line[i].isalpha() or line[i] == '_'):
                            # $NAME
                            start = i
                            while i < n and (line[i].isalnum() or line[i] == '_'):
                                i += 1
                            name = line[start:i]
                            if name in env:
                                text.append(env[name])
                            else:
                                text.append('')
                        else:
                            # $ not followed by name or {, literal
                            text.append('$')
                    else:
                        text.append(line[i])
                        i += 1
                if i >= n:
                    raise ValueError("Unterminated double quote")
                i += 1  # skip closing quote
                word_segments.append((''.join(text), True))
                all_unquoted_expansions = False
            elif c == '\\':
                # Unquoted backslash
                if i + 1 < n:
                    next_c = line[i + 1]
                    if next_c == '\n':
                        # Backslash-newline is removed
                        i += 2
                    else:
                        word_segments.append((next_c, False))
                        i += 2
                else:
                    raise ValueError("Trailing unescaped backslash")
            elif c == '$':
                # Unquoted expansion
                i += 1
                if i < n and line[i] == '{':
                    # ${...}
                    i += 1
                    start = i
                    while i < n and line[i] != '}':
                        i += 1
                    if i >= n:
                        raise ValueError("Unterminated ${")
                    inner = line[start:i]
                    i += 1  # skip }
                    if ':-' in inner:
                        name, default = inner.split(':-', 1)
                        if name not in env or env[name] == '':
                            default_expanded = expand_string(default, env)
                            word_segments.append((default_expanded, False))
                            expansion_total += default_expanded
                        else:
                            word_segments.append((env[name], False))
                            expansion_total += env[name]
                    elif '-' in inner:
                        name, default = inner.split('-', 1)
                        if name not in env:
                            default_expanded = expand_string(default, env)
                            word_segments.append((default_expanded, False))
                            expansion_total += default_expanded
                        else:
                            word_segments.append((env[name], False))
                            expansion_total += env[name]
                    else:
                        name = inner
                        if name in env:
                            word_segments.append((env[name], False))
                            expansion_total += env[name]
                        else:
                            word_segments.append(('', False))
                elif i < n and (line[i].isalpha() or line[i] == '_'):
                    # $NAME
                    start = i
                    while i < n and (line[i].isalnum() or line[i] == '_'):
                        i += 1
                    name = line[start:i]
                    if name in env:
                        word_segments.append((env[name], False))
                        expansion_total += env[name]
                    else:
                        word_segments.append(('', False))
                else:
                    # $ not followed by name or {, literal
                    word_segments.append(('$', False))
                    all_unquoted_expansions = False
            else:
                # Regular character
                word_segments.append((c, False))
                all_unquoted_expansions = False
                i += 1

        # Now, process the word
        if not word_segments:
            continue

        # Check if the word is entirely an unquoted expansion that becomes empty
        if all_unquoted_expansions and expansion_total == '' and not had_empty_quoted:
            # Remove this word
            continue

        # Field splitting
        final_words = []
        current_word_parts = []
        in_word = False

        for text, is_quoted in word_segments:
            if is_quoted:
                if text:
                    current_word_parts.append(text)
                    in_word = True
                else:
                    # Empty quoted string
                    in_word = True
                    had_empty_quoted = True
            else:
                for char in text:
                    if char in ' \t\n':
                        if in_word:
                            final_words.append(''.join(current_word_parts))
                            current_word_parts = []
                            in_word = False
                    else:
                        current_word_parts.append(char)
                        in_word = True

        if in_word:
            final_words.append(''.join(current_word_parts))

        # If final_words is empty, it means the word was empty
        # Check if it was from an empty quoted string
        if not final_words:
            # Check if there was an empty quoted string
            if had_empty_quoted:
                final_words.append('')
            # Otherwise, it was from an empty unquoted expansion, which we already handled

        words.extend(final_words)

    return words
