from __future__ import annotations

import dataclasses
import typing
from typing import Any, get_type_hints


class LoadError(ValueError):
    def __init__(self, path: str, message: str):
        self.path = path
        super().__init__(f"{path}: {message}")


def _resolve_annotation(annotation: Any, module_globals: dict) -> Any:
    """Resolve string annotations using get_type_hints."""
    if isinstance(annotation, str):
        # Try to resolve using the module's globals
        try:
            return eval(annotation, module_globals)
        except Exception:
            return annotation
    return annotation


def _get_type_hints(cls: type) -> dict:
    """Get type hints for a dataclass, resolving string annotations."""
    module = cls.__module__
    try:
        import sys
        mod = sys.modules.get(module)
        if mod is not None:
            globals_dict = vars(mod)
        else:
            globals_dict = {}
    except Exception:
        globals_dict = {}

    # Add the class itself and its module's globals
    globals_dict = dict(globals_dict)
    globals_dict[cls.__name__] = cls

    try:
        return get_type_hints(cls, globalns=globals_dict)
    except Exception:
        # Fallback: try without globalns
        return get_type_hints(cls)


def _load_value(annotation: Any, data: Any, path: str, module_globals: dict) -> Any:
    """Load a value from data according to the annotation."""

    # Handle Optional[T] / T | None
    if _is_optional(annotation):
        if data is None:
            return None
        # Non-null data: load the inner type
        inner = _get_optional_inner(annotation)
        return _load_value(inner, data, path, module_globals)

    # Handle Union types (non-Optional)
    if _is_union(annotation):
        members = _get_union_members(annotation)
        # Try each member left to right
        last_error = None
        for member in members:
            try:
                return _load_value(member, data, path, module_globals)
            except LoadError as e:
                last_error = e
            except Exception:
                last_error = LoadError(path, f"failed to load {member}")
        # If none loaded, raise with the union's own path
        raise LoadError(path, f"could not load value as union {annotation}")

    # Handle Literal
    if _is_literal(annotation):
        literals = _get_literal_values(annotation)
        for lit in literals:
            if data == lit and type(data) == type(lit):
                return data
        raise LoadError(path, f"value {data!r} is not a valid literal for {annotation}")

    # Handle nested dataclasses
    if _is_dataclass(annotation):
        return _load_dataclass(annotation, data, path, module_globals)

    # Handle list[T]
    if _is_list(annotation):
        return _load_list(annotation, data, path, module_globals)

    # Handle dict[str, T]
    if _is_dict(annotation):
        return _load_dict(annotation, data, path, module_globals)

    # Handle tuple[T, ...] (variable length)
    if _is_variable_tuple(annotation):
        return _load_variable_tuple(annotation, data, path, module_globals)

    # Handle fixed-length tuple[A, B, C]
    if _is_fixed_tuple(annotation):
        return _load_fixed_tuple(annotation, data, path, module_globals)

    # Handle basic types
    if annotation is int:
        if isinstance(data, bool):
            raise LoadError(path, f"expected int, got bool")
        if isinstance(data, int):
            return data
        raise LoadError(path, f"expected int, got {type(data).__name__}")

    if annotation is float:
        if isinstance(data, bool):
            raise LoadError(path, f"expected float, got bool")
        if isinstance(data, int):
            return float(data)
        if isinstance(data, float):
            return data
        raise LoadError(path, f"expected float, got {type(data).__name__}")

    if annotation is str:
        if isinstance(data, str):
            return data
        raise LoadError(path, f"expected str, got {type(data).__name__}")

    if annotation is bool:
        if isinstance(data, bool):
            return data
        raise LoadError(path, f"expected bool, got {type(data).__name__}")

    if annotation is type(None):
        if data is None:
            return None
        raise LoadError(path, f"expected None, got {type(data).__name__}")

    # Fallback: if annotation is a type, check isinstance
    if isinstance(annotation, type):
        if isinstance(data, annotation):
            return data
        raise LoadError(path, f"expected {annotation.__name__}, got {type(data).__name__}")

    raise LoadError(path, f"unsupported annotation {annotation}")


def _is_optional(annotation: Any) -> bool:
    """Check if annotation is Optional[T] or T | None."""
    if _is_union(annotation):
        members = _get_union_members(annotation)
        return type(None) in members
    return False


def _get_optional_inner(annotation: Any) -> Any:
    """Get the inner type of Optional[T]."""
    members = _get_union_members(annotation)
    for m in members:
        if m is not type(None):
            return m
    raise ValueError("No inner type found in Optional")


def _is_union(annotation: Any) -> bool:
    """Check if annotation is a Union type."""
    origin = getattr(annotation, '__origin__', None)
    if origin is typing.Union:
        return True
    # Python 3.10+ uses types.UnionType for X | Y
    import types
    if isinstance(annotation, types.UnionType):
        return True
    return False


def _get_union_members(annotation: Any) -> list:
    """Get the members of a Union type."""
    args = getattr(annotation, '__args__', None)
    if args is not None:
        return list(args)
    # Python 3.10+ UnionType
    import types
    if isinstance(annotation, types.UnionType):
        return list(annotation.__args__)
    return []


def _is_literal(annotation: Any) -> bool:
    """Check if annotation is a Literal type."""
    origin = getattr(annotation, '__origin__', None)
    if origin is typing.Literal:
        return True
    return False


def _get_literal_values(annotation: Any) -> list:
    """Get the literal values from a Literal type."""
    args = getattr(annotation, '__args__', None)
    if args is not None:
        return list(args)
    return []


def _is_dataclass(annotation: Any) -> bool:
    """Check if annotation is a dataclass type."""
    return isinstance(annotation, type) and dataclasses.is_dataclass(annotation)


def _is_list(annotation: Any) -> bool:
    """Check if annotation is list[T]."""
    origin = getattr(annotation, '__origin__', None)
    return origin is list


def _is_dict(annotation: Any) -> bool:
    """Check if annotation is dict[str, T]."""
    origin = getattr(annotation, '__origin__', None)
    return origin is dict


def _is_variable_tuple(annotation: Any) -> bool:
    """Check if annotation is tuple[T, ...]."""
    origin = getattr(annotation, '__origin__', None)
    if origin is not tuple:
        return False
    args = getattr(annotation, '__args__', None)
    if args is None:
        return False
    # tuple[T, ...] has args (T, Ellipsis)
    return len(args) == 2 and args[1] is Ellipsis


def _is_fixed_tuple(annotation: Any) -> bool:
    """Check if annotation is a fixed-length tuple like tuple[A, B, C]."""
    origin = getattr(annotation, '__origin__', None)
    if origin is not tuple:
        return False
    args = getattr(annotation, '__args__', None)
    if args is None:
        return False
    # Fixed tuple has no Ellipsis
    return Ellipsis not in args


def _load_dataclass(cls: type, data: Any, path: str, module_globals: dict) -> Any:
    """Load a dataclass instance from data."""
    if not isinstance(data, dict):
        raise LoadError(path, f"expected dict for dataclass {cls.__name__}, got {type(data).__name__}")

    hints = _get_type_hints(cls)
    fields = dataclasses.fields(cls)

    # Check for unknown keys
    known_keys = set(f.name for f in fields)
    for key in data:
        if key not in known_keys:
            raise LoadError(f"{path}.{key}", f"unknown key '{key}'")

    # Build kwargs
    kwargs = {}
    for field in fields:
        field_name = field.name
        field_path = f"{path}.{field_name}"

        if field_name in data:
            value = data[field_name]
            annotation = hints.get(field_name, field.type)
            kwargs[field_name] = _load_value(annotation, value, field_path, module_globals)
        else:
            # Missing key: use default or default_factory
            if field.default is not dataclasses.MISSING:
                kwargs[field_name] = field.default
            elif field.default_factory is not dataclasses.MISSING:
                kwargs[field_name] = field.default_factory()
            else:
                raise LoadError(field_path, f"missing required field '{field_name}'")

    return cls(**kwargs)


def _load_list(annotation: Any, data: Any, path: str, module_globals: dict) -> Any:
    """Load a list[T] from data."""
    if not isinstance(data, list):
        raise LoadError(path, f"expected list, got {type(data).__name__}")

    args = getattr(annotation, '__args__', None)
    if args is None or len(args) == 0:
        raise LoadError(path, "list annotation missing type argument")

    inner_type = args[0]
    result = []
    for i, item in enumerate(data):
        item_path = f"{path}[{i}]"
        result.append(_load_value(inner_type, item, item_path, module_globals))
    return result


def _load_dict(annotation: Any, data: Any, path: str, module_globals: dict) -> Any:
    """Load a dict[str, T] from data."""
    if not isinstance(data, dict):
        raise LoadError(path, f"expected dict, got {type(data).__name__}")

    args = getattr(annotation, '__args__', None)
    if args is None or len(args) != 2:
        raise LoadError(path, "dict annotation missing type arguments")

    key_type, value_type = args[0], args[1]

    # Validate keys are strings
    for key in data:
        if not isinstance(key, str):
            raise LoadError(f"{path}.{key}", f"expected str key, got {type(key).__name__}")

    result = {}
    for key, value in data.items():
        value_path = f"{path}.{key}"
        result[key] = _load_value(value_type, value, value_path, module_globals)
    return result


def _load_variable_tuple(annotation: Any, data: Any, path: str, module_globals: dict) -> Any:
    """Load a tuple[T, ...] from data."""
    if not isinstance(data, list):
        raise LoadError(path, f"expected list for tuple, got {type(data).__name__}")

    args = getattr(annotation, '__args__', None)
    if args is None or len(args) != 2:
        raise LoadError(path, "variable tuple annotation missing type argument")

    inner_type = args[0]
    result = []
    for i, item in enumerate(data):
        item_path = f"{path}[{i}]"
        result.append(_load_value(inner_type, item, item_path, module_globals))
    return tuple(result)


def _load_fixed_tuple(annotation: Any, data: Any, path: str, module_globals: dict) -> Any:
    """Load a fixed-length tuple[A, B, C] from data."""
    if not isinstance(data, list):
        raise LoadError(path, f"expected list for tuple, got {type(data).__name__}")

    args = getattr(annotation, '__args__', None)
    if args is None:
        raise LoadError(path, "fixed tuple annotation missing type arguments")

    if len(data) != len(args):
        raise LoadError(path, f"expected tuple of length {len(args)}, got {len(data)}")

    result = []
    for i, (item, elem_type) in enumerate(zip(data, args)):
        item_path = f"{path}[{i}]"
        result.append(_load_value(elem_type, item, item_path, module_globals))
    return tuple(result)


def load(cls: type, data: Any) -> Any:
    """Build an instance of a (possibly nested) @dataclass type cls from JSON-like data."""
    module_globals = {}
    try:
        import sys
        mod = sys.modules.get(cls.__module__)
        if mod is not None:
            module_globals = vars(mod)
    except Exception:
        pass

    return _load_dataclass(cls, data, "$", module_globals)
